type client struct {
	url, token string
}

func (c *client) run(ctx context.Context, s stream, t0 time.Time) *result {
	r := &result{s: s}
	body := map[string]any{
		"model":          "llm",
		"stream":         true,
		"stream_options": map[string]any{"include_usage": true},
		"temperature":    0,
		"max_tokens":     s.max,
		"messages": []map[string]string{
			{"role": "system", "content": s.system},
			{"role": "user", "content": s.user},
		},
	}
	if s.effort != "" {
		body["reasoning_effort"] = s.effort
	}
	b, _ := json.Marshal(body)
	req, err := http.NewRequestWithContext(ctx, "POST", c.url+"/v1/chat/completions", bytes.NewReader(b))
	if err != nil {
		r.err = err
		return r
	}
	req.Header.Set("Content-Type", "application/json")
	if s.class != "" {
		req.Header.Set("X-Priority", s.class)
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	r.start = time.Now()
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		r.err = err
		return r
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		msg, _ := io.ReadAll(resp.Body)
		r.err = fmt.Errorf("%s: %s", resp.Status, bytes.TrimSpace(msg))
		return r
	}
	sc := bufio.NewScanner(resp.Body)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		line, ok := strings.CutPrefix(sc.Text(), "data: ")
		if !ok {
			continue
		}
		if line == "[DONE]" {
			break
		}
		var f struct {
			Choices []struct {
				Delta struct {
					Content          string `json:"content"`
					ReasoningContent string `json:"reasoning_content"`
				} `json:"delta"`
				FinishReason *string `json:"finish_reason"`
			} `json:"choices"`
			Usage *struct {
				PromptTokens     int `json:"prompt_tokens"`
				CompletionTokens int `json:"completion_tokens"`
			} `json:"usage"`
			Error *struct {
				Message string `json:"message"`
			} `json:"error"`
		}
		if err := json.Unmarshal([]byte(line), &f); err != nil {
			r.err = err
			return r
		}
		if f.Error != nil {
			r.err = fmt.Errorf("%s", f.Error.Message)
			return r
		}
		if f.Usage != nil {
			r.prompt, r.compl = f.Usage.PromptTokens, f.Usage.CompletionTokens
		}
		for _, ch := range f.Choices {
			if ch.FinishReason != nil {
				r.finish = *ch.FinishReason
			}
			if ch.Delta.Content == "" && ch.Delta.ReasoningContent == "" {
				continue
			}
			now := time.Now()
			if r.deltas == 0 {
				r.first = now
			}
			r.last = now
			r.deltas++
		}
	}
	if err := sc.Err(); err != nil {
		r.err = err
	}
	if r.deltas == 0 && r.err == nil {
		r.err = fmt.Errorf("no deltas")
	}
	return r
}

