// the lock straight back, and hands off only to a waiter that has already
// starved for a millisecond, so a plain Unlock-Lock would usually give nobody
// anything.
func (d *Device) yield() bool {
	if d.waiting.Load() == 0 {
		return false
	}
	n := d.acquired.Load()
	d.mu.Unlock()
	for d.acquired.Load() == n {
		runtime.Gosched()
	}
	d.waiting.Add(1)
	d.mu.Lock()
	d.waiting.Add(-1)
	d.acquired.Add(1)
	return true
}'''),
