package backend

import (
	"bytes"
	"context"
	"encoding/base64"
	"image"
	_ "image/jpeg"
	"image/png"
	"os"
	"testing"

	"strix-halo-vulkan/api"
	"strix-halo-vulkan/llm"
)

const visionTestMMProj = "../models/Qwen3.8-Flash-Next-GGUF/mmproj-BF16.gguf"

// mirrorURL is an image flipped left to right, as a PNG data: URL.
func mirrorURL(t *testing.T, path string) string {
func TestVisionCacheEvictsOldest(t *testing.T) {
	v := &llmVision{maxCache: 3 * 400}
	img := func(h uint64) llm.PromptImage { return llm.PromptImage{Hash: h, Embd: make([]float32, 100)} }
	v.store(img(1))
	v.store(img(2))
	v.store(img(3))
	if _, ok := v.lookup(1); !ok {
		t.Fatal("image 1 is not cached")
	}
	v.store(img(4)) // evicts 2, the oldest since 1 was just used
	for h, want := range map[uint64]bool{1: true, 2: false, 3: true, 4: true} {
		if _, ok := v.lookup(h); ok != want {
			t.Errorf("image %d cached %v, want %v", h, ok, want)
		}
	}
	if v.cached != 3*400 {
		t.Errorf("%d bytes held, want %d", v.cached, 3*400)
	}
	v.store(llm.PromptImage{Hash: 9, Embd: make([]float32, 1000)}) // larger than the whole budget
	if _, ok := v.lookup(9); ok {
		t.Error("an image over the whole budget was cached")
	}
}
	// job is the request holding the slot, or nil when it is free.
	job *llmJob
	// used is when it was last released, for least-recently-used.
	used time.Time
	// ckpt is the slot's checkpoint, or nil. It is usable only while held
	// still starts with its tokens: that is what says the cache cells below
	// it are still the ones it was taken over (llm.Graph.Restore).
	ckpt *llm.Checkpoint
	// ckptKeys is the checkpoint's sequence as keys: its ids, with an
	// image's cells named by the picture rather than by the pad every one of
	// them holds (llm_vision.go). held is keys too.
	ckptKeys []int32
}

// reuse is how much of a prompt the slot saves, and whether that is by
// restoring its checkpoint rather than continuing what it holds.
func (sl *llmSlot) reuse(prompt []int32) (int, bool) {
	n := usablePrefix(sl.held, prompt)
	if c := sl.ckpt; c != nil {
		b := c.Past()
		if b > n && b < len(prompt) && commonPrefix(sl.held, sl.ckptKeys) == b && commonPrefix(prompt, sl.ckptKeys) == b {
			return b, true
		}
	}
	return n, false
}

// llmJob is one request's claim on the scheduler.
type llmJob struct {
	ctx   context.Context
	class llmClass
	slot  int
	// reused is how many leading tokens of the prompt the slot already held,
	// and restore whether that is its checkpoint rather than its sequence.
	reused  int
	restore bool

